#[test]
fn meters() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(Length::from_meters(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(Length::from_base(base).as_meters(), back, F64_TOL);
        assert_close(Length::from_meters(v).as_meters(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Length::from_meters(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Length::from_base(base as f32).as_meters() as f64,
            back,
            F32_TOL,
        );
    }
}

